// phrase-mappings-001-missing: A claimed Scenario with a missing Phrase mapping must fail naming its phrase without an AI turn
func TestPhraseMappings001Missing(t *testing.T) {
	s := scenarios.New(t, "phrase-mappings-001-missing")
	s.Given(`the "phrase-mappings-missing" project tree`)
	s.When(`the System Architect runs "scen check"`)
	s.Then(`the command exits with code 1`)
	s.And(`the engine dispatched 0 AI turns`)
	s.And(`stdout matches phrase.*the greeting is requested`)
	s.And(`no file outside "tmp" changed`)
	s.Done()
}

